    "Description": "Event: a user rotates the winding knob to a target angle at a point in time. The README's §1 input event.",
    "schema": [
      {
        "name": "WindActionId",
        "datatype": "string",
        "type": "raw",
        "nullable": false,
        "Description": "Primary key."
      },
      {
        "name": "PerformedBy",
        "datatype": "string",
        "type": "relationship",
        "nullable": false,
        "Description": "Acting user.",
        "RelatedTo": "Users"
      },
      {
        "name": "TurnedKnob",
        "datatype": "string",
        "type": "relationship",
        "nullable": false,
        "Description": "Knob that was turned.",
        "RelatedTo": "WindingKnobs"
      },
      {
        "name": "TargetAngleDeg",
        "datatype": "number",
        "type": "raw",
        "nullable": false,
        "Description": "Angle wound to, in degrees."
      },
      {
        "name": "OccurredAt",
        "datatype": "datetime",
        "type": "raw",
        "nullable": false,
        "Description": "When the wind happened."
      },
      {
        "name": "AppliedToTimer",
        "datatype": "string",
        "type": "lookup",
        "nullable": false,
        "Description": "Timer the turned knob is fixed to.",
        "formula": "=INDEX(WindingKnobs!{{FixedToTimer}}, MATCH({{TurnedKnob}}, WindingKnobs!{{WindingKnobId}}, 0))"
      },
      {
        "name": "ResultedInRing",
        "datatype": "boolean",
        "type": "lookup",
        "nullable": false,
        "Description": "True if the timer this wind action wound has since rung.",
        "formula": "=INDEX(Timers!{{HasRung}}, MATCH({{AppliedToTimer}}, Timers!{{TimerId}}, 0))"
      }
    ],
