      "Timers.MechanicalPhase": {
        "table": "Timers",
        "field": "MechanicalPhase",
        "kind": "formula",
        "rule": "Das Feld „Mechanical Phase“ des Timer wird nach folgender Priorität bestimmt:\n1. „rung“, wenn das Kennzeichen „Has Rung“ gesetzt ist;\n2. „freshly-wound“, wenn die Wind Fraction größer ist als 0.8;\n3. „mid-run“, wenn die Wind Fraction größer ist als 0.25;\n4. andernfalls „nearly-done“.",
        "mechanical": false,
        "refs": [
          {
            "table": "Timers",
            "field": "HasRung",
            "label": "has rung"
          },
          {
            "table": "Timers",
            "field": "WindFraction",
            "label": "wind fraction"
          }
        ],
        "structure": {
          "kind": "priority",
          "headline": "Das Feld „Mechanical Phase“ des Timer wird nach folgender Priorität bestimmt:",
          "cases": [
            {
              "value": "„rung“",
              "when": {
                "kind": "leaf",
                "text": "das Kennzeichen „Has Rung“ gesetzt ist"
              }
            },
            {
              "value": "„freshly-wound“",
              "when": {
                "kind": "leaf",
                "text": "die Wind Fraction größer ist als 0.8"
              }
            },
            {
              "value": "„mid-run“",
              "when": {
                "kind": "leaf",
                "text": "die Wind Fraction größer ist als 0.25"
              }
            },
            {
              "value": "„nearly-done“",
              "when": null
            }
          ],
          "children": null
        },
        "plain": "Wenn Has Rung, dann \"rung\", andernfalls wenn Wind Fraction größer als 0.8 ist, dann \"freshly-wound\", andernfalls wenn Wind Fraction größer als 0.25 ist, dann \"mid-run\", andernfalls \"nearly-done\""
      },
