    "obligations": [],
    "structural": {
      "Users": [
        "userは display name を持た**なければなりません**。"
      ],
      "Timers": [
        "timerは label、wind angle degrees、max wind degrees、max spring torque nm、およびescapement base hz を持た**なければなりません**。"
      ],
      "Cases": [
        "caseは、houses timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "caseは material を持た**なければなりません**。"
      ],
      "Bells": [
        "bellは、mounted on caseとして「case」をちょうど 1 件参照し**なければなりません**。",
        "bellは diameter mmおよびtone hz を持た**なければなりません**。"
      ],
      "WindingKnobs": [
        "winding knobは、fixed to timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "winding knobは scale min、scale max、wind direction、およびshaft diameter mm を持た、かつ 「Pointer Fixed」であるかどうかを記録し**なければなりません**。"
      ],
      "Arbors": [
        "arborは、in timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "arborは diameter mm を持た**なければなりません**。"
      ],
      "Mainsprings": [
        "mainspringは、wrapped on arborとして「arbor」をちょうど 1 件参照し**なければなりません**。",
        "mainspringは drum diameter mm、material、inner end anchor、およびouter end anchor を持た**なければなりません**。"
      ],
      "GearTrains": [
        "gear trainは、in timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "gear trainは reduction ratio を持た**なければなりません**。"
      ],
      "Gears": [
        "gearは、in gear trainとして「gear train」をちょうど 1 件参照し**なければなりません**。",
        "gearは position in chainおよびtooth count を持た**なければなりません**。"
      ],
      "OutputShafts": [
        "output shaftは、in gear trainとして「gear train」をちょうど 1 件参照し**なければなりません**。"
      ],
      "DialPointers": [
        "dial pointerは、on output shaftとして「output shaft」をちょうど 1 件参照し**なければなりません**。",
        "dial pointerは length mm を持た**なければなりません**。"
      ],
      "Escapements": [
        "escapementは、in timerとして「timer」をちょうど 1 件参照し**なければなりません**。"
      ],
      "EscapementWheels": [
        "escapement wheelは、in escapementとして「escapement」をちょうど 1 件参照し**なければなりません**。",
        "escapement wheelは tooth count を持た**なければなりません**。"
      ],
      "Pallets": [
        "palletは、in escapementとして「escapement」をちょうど 1 件参照し**なければなりません**。",
        "palletは prong countおよびmass grams を持た**なければなりません**。"
      ],
      "Hairsprings": [
        "hairspringは、attached to palletとして「pallet」をちょうど 1 件参照し**なければなりません**。",
        "hairspringは stiffness nm per rad を持た**なければなりません**。"
      ],
      "Cams": [
        "camは、on arborとして「arbor」をちょうど 1 件参照し**なければなりません**。",
        "camは notch angle deg を持た**なければなりません**。"
      ],
      "BellHammers": [
        "bell hammerは、in timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "bell hammerは arm torque nm を持た**なければなりません**。"
      ],
      "HammerArms": [
        "hammer armは、of bell hammerとして「bell hammer」をちょうど 1 件参照し**なければなりません**。",
        "hammer armは length mm を持た**なければなりません**。"
      ],
      "Strikers": [
        "strikerは、on armとして「hammer arm」をちょうど 1 件参照し**なければなりません**。",
        "strikerは material を持た**なければなりません**。"
      ],
      "HammerCatches": [
        "hammer catchは、of bell hammerとして「bell hammer」をちょうど 1 件参照し**なければなりません**。",
        "hammer catchは、engaged with camとして「cam」をちょうど 1 件参照し**なければなりません**。"
      ],
      "WindActions": [
        "wind actionは、performed byとして「user」をちょうど 1 件参照し**なければなりません**。",
        "wind actionは、turned knobとして「winding knob」をちょうど 1 件参照し**なければなりません**。",
        "wind actionは target angle degおよびoccurred at を持た**なければなりません**。"
      ],
      "TickEvents": [
        "tick eventは、happened on timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "tick eventは、at escapementとして「escapement」をちょうど 1 件参照し**なければなりません**。",
        "tick eventは occurred at を持た**なければなりません**。"
      ],
      "RingEvents": [
        "ring eventは、happened on timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "ring eventは、struckとして「bell」をちょうど 1 件参照し**なければなりません**。",
        "ring eventは occurred at を持た**なければなりません**。"
      ],
      "Cooks": [
        "cookは、on timerとして「timer」をちょうど 1 件参照し**なければなりません**。",
        "cookは、prepared byとして「user」をちょうど 1 件参照し**なければなりません**。",
        "cookは、follows recipeとして「recipe」をちょうど 1 件参照し**なければなりません**。",
        "cookは dish nameおよびstarted at を持た**なければなりません**。"
      ],
      "Recipes": [
        "recipeは dish name、recommended minutes、およびideal temperature c を持た**なければなりません**。"
      ],
      "Kitchens": [
        "kitchenは display name を持た**なければなりません**。"
      ]
    },
    "connectors": {
      "allOf": "次のすべてが成り立つ",
      "anyOf": "次のいずれかが成り立つ",
      "if": "条件:",
      "otherwise": "それ以外の場合",
      "sentenceEnd": "。"
    },
