      "Timers.MechanicalPhase": {
        "table": "Timers",
        "field": "MechanicalPhase",
        "kind": "formula",
        "rule": "O campo “mechanical phase” do timer é determinado pela seguinte prioridade:\n1. “rung”, se o indicador “rung” está ativado;\n2. “freshly-wound”, se o wind fraction é maior que 0.8;\n3. “mid-run”, se o wind fraction é maior que 0.25;\n4. em todos os outros casos, “nearly-done”.",
        "mechanical": false,
        "refs": [
          {
            "table": "Timers",
            "field": "HasRung",
            "label": "has rung"
          },
          {
            "table": "Timers",
            "field": "WindFraction",
            "label": "wind fraction"
          }
        ],
        "structure": {
          "kind": "priority",
          "headline": "O campo “mechanical phase” do timer é determinado pela seguinte prioridade:",
          "cases": [
            {
              "value": "“rung”",
              "when": {
                "kind": "leaf",
                "text": "o indicador “rung” está ativado"
              }
            },
            {
              "value": "“freshly-wound”",
              "when": {
                "kind": "leaf",
                "text": "o wind fraction é maior que 0.8"
              }
            },
            {
              "value": "“mid-run”",
              "when": {
                "kind": "leaf",
                "text": "o wind fraction é maior que 0.25"
              }
            },
            {
              "value": "“nearly-done”",
              "when": null
            }
          ],
          "children": null
        },
        "plain": "Se has rung, então \"rung\", caso contrário se wind fraction é maior que 0.8, então \"freshly-wound\", caso contrário se wind fraction é maior que 0.25, então \"mid-run\", caso contrário \"nearly-done\""
      },
